// ============================================================
// MCP - Transcriber : provider / modele / cle / contenu recus,
// jamais devines. Cf. azy.daily#295 §1 et #329.
// ============================================================
const input = $input.first().json;
const body  = input.body || input;
const ctx   = body.context || {};

const lire = (...cles) => {
  for (const c of cles) {
    const v = ctx[c] !== undefined ? ctx[c] : body[c];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
};

const erreurs = [];

// --- le quatuor parametre ---
const provider = String(lire('provider') || 'google').toLowerCase();
const model    = lire('model', 'llm') || 'gemini-3.6-flash';
const apiKey   = lire('api_key', 'apiKey', 'google_api_key') || $env.GEMINI_API_KEY || '';
const contenu  = lire('content', 'prompt', 'customInstructions') || '';

// --- la video ---
const videoUrl    = lire('videoUrl', 'video_url', 'url') || '';
const videoBase64 = lire('videoBase64', 'video_base64') || '';
const mimeType    = lire('videoMimeType', 'video_mime_type') || 'video/mp4';

// --- le reste ---
const operation  = lire('operation') || 'transcribe';
const langue     = lire('language', 'outputLanguage') || 'auto';
const debut      = lire('startTime', 'start_offset');
const fin        = lire('endTime', 'end_offset');
const maxTokens  = parseInt(lire('max_tokens', 'maxOutputTokens') || 16384, 10);
const temperature = parseFloat(lire('temperature') ?? 0);

// --- tracage (jamais bloquant) ---
const userId  = lire('user_id')  || null;
const guildId = lire('guild_id') || null;

if (!videoUrl && !videoBase64) erreurs.push('videoUrl ou videoBase64 requis');
if (!apiKey) erreurs.push('api_key absente du corps et GEMINI_API_KEY absente de environnement');
if (provider !== 'google') {
  erreurs.push('provider "' + provider + '" non supporte : seul google ingere une URL video nativement');
}
// On NE valide PAS le nom du modele : il est recu, pas devine (#295 §1).

if (erreurs.length > 0) {
  return [{ json: { valide: false, statut: 400, erreurs, user_id: userId, guild_id: guildId } }];
}

// --- consigne par defaut, ecrasee par `content` si fourni ---
const CONSIGNES = {
  transcribe:
    'Transcris integralement la parole de cette video. Rends le texte seul, sans commentaire, ' +
    'en horodatant chaque prise de parole au format [MM:SS].',
  identifySpeakers:
    'Identifie les intervenants de cette video et attribue chaque prise de parole, au format [MM:SS] Locuteur : texte.',
  extractOcr:
    'Releve tout texte visible a image dans cette video, horodate au format [MM:SS].',
  analyzeScene:
    'Decris les scenes successives de cette video, horodatees au format [MM:SS].',
  extractSlides:
    'Restitue le contenu des diapositives affichees dans cette video, horodatees au format [MM:SS].',
};
let consigne = contenu || CONSIGNES[operation] || CONSIGNES.transcribe;
if (langue && langue !== 'auto') {
  consigne += '\nRedige la reponse en langue "' + langue + '".';
}

// --- partie video : URL distante (Google va la chercher) ou base64 televerse ---
const partieVideo = videoBase64
  ? { inline_data: { mime_type: mimeType, data: videoBase64 } }
  : { file_data: { file_uri: videoUrl } };

// --- bornage temporel : mesure le 2026-09-04, 8 s sur 19 s = 705 jetons contre 1676 ---
const secondes = (v) => {
  if (v === undefined || v === null || v === '') return undefined;
  if (typeof v === 'number') return Math.max(0, Math.trunc(v));
  const p = String(v).split(':').map(Number);
  if (p.some(isNaN)) return undefined;
  if (p.length === 3) return p[0] * 3600 + p[1] * 60 + p[2];
  if (p.length === 2) return p[0] * 60 + p[1];
  return Math.max(0, Math.trunc(p[0]));
};
const sDebut = secondes(debut);
const sFin   = secondes(fin);
if (!videoBase64 && (sDebut !== undefined || sFin !== undefined)) {
  partieVideo.video_metadata = {};
  if (sDebut !== undefined) partieVideo.video_metadata.start_offset = { seconds: sDebut };
  if (sFin   !== undefined) partieVideo.video_metadata.end_offset   = { seconds: sFin };
}

const corps = {
  contents: [{ role: 'user', parts: [partieVideo, { text: consigne }] }],
  generationConfig: { maxOutputTokens: maxTokens, temperature },
};

return [{ json: {
  valide: true,
  provider, model, api_key: apiKey,
  operation, langue, corps,
  source: videoBase64 ? 'base64' : 'url',
  video_url: videoUrl || null,
  user_id: userId, guild_id: guildId,
  debut_ms: Date.now(),
} }];

// ============================================================
// Lecture du VRAI statut. `fullResponse + neverError` couvre les
// erreurs HTTP ; `onError` couvre les pannes de transport, qui
// n emettent PAS de statusCode. Cf. azy.daily#442 et n8n-workflows#467.
// ============================================================
const entree = $input.first().json;
const amont  = $('Validate Input').first().json;

let statut = entree.statusCode;
if (statut === undefined) {
  const brut = String(entree?.error?.message || entree?.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  statut = m ? parseInt(m[1], 10) : ((entree?.error || entree?.code) ? 502 : 200);
}

const charge = entree.body !== undefined ? entree.body : entree;

if (statut >= 400 || !charge || charge.error) {
  const msg = charge?.error?.message || entree?.error?.message || entree?.message || 'echec amont';
  return [{ json: {
    success: false,
    statut,
    error: { code: statut, message: String(msg).slice(0, 500), status: charge?.error?.status || 'UPSTREAM_ERROR' },
    provider: amont.provider, model: amont.model, operation: amont.operation,
  } }];
}

const cand = (charge.candidates || [])[0];
const texte = ((cand?.content?.parts) || []).map((p) => p.text || '').join('').trim();

if (!texte) {
  const motif = cand?.finishReason || 'REPONSE_VIDE';
  return [{ json: {
    success: false,
    statut: 502,
    error: { code: 502, message: 'Gemini a repondu sans texte (finishReason=' + motif + ')', status: 'EMPTY_RESPONSE' },
    provider: amont.provider, model: amont.model, operation: amont.operation,
  } }];
}

// usage : convention arretee en azy.daily#287/#295, plus le detail par modalite
const u = charge.usageMetadata || {};
const parModalite = {};
for (const d of (u.promptTokensDetails || [])) {
  if (d && d.modality) parModalite[String(d.modality).toLowerCase()] = d.tokenCount || 0;
}

return [{ json: {
  success: true,
  statut: 200,
  provider: amont.provider,
  // `model` = le modele REELLEMENT servi, lu dans modelVersion. Un alias est
  // resolu par Google : gemini-flash-latest -> gemini-3.8-flash (mesure du
  // 2026-09-04). Reemettre le modele demande rendrait aveugle tout controle
  // de facturation en aval, qui comparerait un echo de sa propre requete.
  model: charge.modelVersion || amont.model,
  model_requested: amont.model,
  operation: amont.operation,
  language: amont.langue,
  source: amont.source,
  video_url: amont.video_url,
  transcript: texte,
  data: { transcript: texte },
  usage: {
    prompt_tokens: u.promptTokenCount || 0,
    completion_tokens: (u.candidatesTokenCount || 0) + (u.thoughtsTokenCount || 0),
    total_tokens: u.totalTokenCount || 0,
    cache_read_input_tokens: u.cachedContentTokenCount || 0,
    cache_creation_input_tokens: 0,
    reasoning_tokens: u.thoughtsTokenCount || 0,
    prompt_tokens_by_modality: parModalite,
  },
  duree_ms: Date.now() - (amont.debut_ms || Date.now()),
  user_id: amont.user_id,
  guild_id: amont.guild_id,
} }];

const e = $input.first().json;
return [{ json: {
  success: false,
  statut: e.statut || 400,
  error: { code: e.statut || 400, message: (e.erreurs || ['requete invalide']).join(', '), status: 'BAD_REQUEST' },
  user_id: e.user_id || null,
  guild_id: e.guild_id || null,
} }];

// ============================================
// VALIDATION INPUT - RFC-014 Compatible
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (for tracing only, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Extract video source ---
const videoUrl_raw = ctx.videoUrl || ctx.video_url || body.videoUrl || body.video_url;
const videoBase64_raw = ctx.videoBase64 || ctx.video_base64 || body.videoBase64 || body.video_base64;
const videoMimeType = ctx.videoMimeType || ctx.video_mime_type || body.videoMimeType || body.video_mime_type || 'video/mp4';

// --- Extract operation parameters ---
const operation = ctx.operation || body.operation || 'transcribe';
const outputLanguage = ctx.language || body.language || 'auto';
const enableChunking = (ctx.enableChunking || body.enableChunking) === true || (ctx.enableChunking || body.enableChunking) === 'true';
const chunkDuration = ctx.chunkDuration || body.chunkDuration || 10;
const videoDuration = ctx.videoDuration || body.videoDuration || 0;
const model = ctx.model || body.model || 'gemini-2.5-flash';
const customInstructions = ctx.customInstructions || body.customInstructions || '';
const startTime = ctx.startTime || body.startTime || '';
const endTime = ctx.endTime || body.endTime || '';
const executionMode = ctx.execution_mode || body.execution_mode || 'online';

// --- Validation ---
const hasVideo = !!(videoUrl_raw || videoBase64_raw);

if (!hasVideo) errors.push('videoUrl or videoBase64 required');

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// --- Determine video source type ---
const hasBase64 = !!videoBase64_raw;
const videoSource = hasBase64 ? 'base64' : 'url';

const result = {
  valid: true,
  videoSource,
  operation,
  outputLanguage,
  enableChunking,
  chunkDuration,
  videoDuration,
  model,
  customInstructions,
  startTime,
  endTime,
  executionMode,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime_ms: Date.now()
};

if (hasBase64) {
  result.videoBase64 = videoBase64_raw;
  result.videoMimeType = videoMimeType;
} else {
  result.videoUrl = videoUrl_raw;
}

return result;

// ============================================
// FORMAT SUCCESS RESPONSE - with _trace
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime_ms;

return {
  success: true,
  data: input,
  meta: {
    provider: 'gemini',
    execution_mode: prevData.executionMode,
    operation: prevData.operation,
    model: prevData.model
  },
  _trace: {
    service_response: {
      operation: prevData.operation,
      model: prevData.model,
      has_transcription: !!input.transcription
    },
    provider: 'gemini',
    mode: prevData.operation,
    latency_ms: Date.now() - startTime,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request
};

// ============================================
// BUILD VALIDATION ERROR - with _trace
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};
